function getRHConfig($pdo){$c=$pdo->query("SELECT * FROM recursos_humanos_config ORDER BY id ASC LIMIT 1")->fetch(PDO::FETCH_ASSOC);if(!$c){$pdo->query("INSERT INTO recursos_humanos_config (hero_titulo,hero_subtitulo,intro_titulo,intro_texto) VALUES ('Recursos Humanos','Transparência, organização e valorização profissional.','Gestão de pessoas com transparência','Texto introdutório.')");$c=$pdo->query("SELECT * FROM recursos_humanos_config ORDER BY id ASC LIMIT 1")->fetch(PDO::FETCH_ASSOC);}return $c;}
function upRH($campo,$dir,$permitidos,&$erro,$prefixo){if(empty($_FILES[$campo]['name']))return'';$ext=strtolower(pathinfo($_FILES[$campo]['name'],PATHINFO_EXTENSION));if(!in_array($ext,$permitidos)){$erro='Formato inválido em '.$campo;return'';}$novo=$prefixo.'_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$ext;if(move_uploaded_file($_FILES[$campo]['tmp_name'],$dir.$novo))return$novo;$erro='Erro ao enviar ficheiro.';return'';}
if($_SERVER['REQUEST_METHOD']==='POST'){$acao=$_POST['acao']??'';if($acao==='config'){$id=(int)$_POST['id'];$vals=[trim($_POST['hero_kicker']??''),trim($_POST['hero_titulo']??''),trim($_POST['hero_subtitulo']??''),trim($_POST['intro_titulo']??''),trim($_POST['intro_texto']??''),trim($_POST['destaque_1_titulo']??''),trim($_POST['destaque_1_valor']??''),trim($_POST['destaque_2_titulo']??''),trim($_POST['destaque_2_valor']??''),trim($_POST['destaque_3_titulo']??''),trim($_POST['destaque_3_valor']??''),$id];if(!$vals[1])$erro='O título principal é obrigatório.';else{$st=$pdo->prepare("UPDATE recursos_humanos_config SET hero_kicker=?,hero_titulo=?,hero_subtitulo=?,intro_titulo=?,intro_texto=?,destaque_1_titulo=?,destaque_1_valor=?,destaque_2_titulo=?,destaque_2_valor=?,destaque_3_titulo=?,destaque_3_valor=?,atualizado_em=NOW() WHERE id=?");$st->execute($vals);$sucesso='Conteúdo principal atualizado.';}} if($acao==='documento'){$id=(int)($_POST['id']??0);$titulo=trim($_POST['titulo']??'');$categoria=trim($_POST['categoria']??'outros');$estado=trim($_POST['estado']??'ativo');$descricao=trim($_POST['descricao']??'');$data=trim($_POST['data_documento']??'');$ordem=(int)($_POST['ordem']??0);$destaque=isset($_POST['destaque'])?1:0;$ativo=isset($_POST['ativo'])?1:0;$fg=$_POST['ficheiro_atual']??'';$fo=$_POST['ficheiro_original_atual']??'';$img=$_POST['imagem_atual']??'';if(!$titulo||!isset($categorias[$categoria])||!isset($estados[$estado]))$erro='Preencha o título, categoria e estado.';if(!$erro&&!empty($_FILES['ficheiro']['name'])){$n=upRH('ficheiro',$uploadDir,['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp'],$erro,'rh_doc');if($n){$fg=$n;$fo=$_FILES['ficheiro']['name'];}}if(!$erro&&!empty($_FILES['imagem']['name'])){$n=upRH('imagem',$uploadDir,['jpg','jpeg','png','webp'],$erro,'rh_img');if($n)$img=$n;}if(!$erro){$dataSql=$data?:null;if($id>0){$st=$pdo->prepare("UPDATE recursos_humanos_documentos SET titulo=?,categoria=?,estado=?,descricao=?,ficheiro_original=?,ficheiro_guardado=?,imagem=?,data_documento=?,ordem=?,destaque=?,ativo=?,atualizado_em=NOW() WHERE id=?");$st->execute([$titulo,$categoria,$estado,$descricao,$fo,$fg,$img,$dataSql,$ordem,$destaque,$ativo,$id]);$sucesso='Documento atualizado.';}else{$st=$pdo->prepare("INSERT INTO recursos_humanos_documentos (titulo,categoria,estado,descricao,ficheiro_original,ficheiro_guardado,imagem,data_documento,ordem,destaque,ativo) VALUES (?,?,?,?,?,?,?,?,?,?,?)");$st->execute([$titulo,$categoria,$estado,$descricao,$fo,$fg,$img,$dataSql,$ordem,$destaque,$ativo]);$sucesso='Documento criado.';}}}}
if(isset($_GET['apagar'])){$pdo->prepare("DELETE FROM recursos_humanos_documentos WHERE id=?")->execute([(int)$_GET['apagar']]);header('Location: recursos-humanos.php');exit;}if(isset($_GET['toggle'])){$pdo->prepare("UPDATE recursos_humanos_documentos SET ativo=IF(ativo=1,0,1),atualizado_em=NOW() WHERE id=?")->execute([(int)$_GET['toggle']]);header('Location: recursos-humanos.php');exit;}
$config=getRHConfig($pdo);$editar=null;if(isset($_GET['editar'])){$st=$pdo->prepare("SELECT * FROM recursos_humanos_documentos WHERE id=?");$st->execute([(int)$_GET['editar']]);$editar=$st->fetch(PDO::FETCH_ASSOC);} $docs=$pdo->query("SELECT * FROM recursos_humanos_documentos ORDER BY destaque DESC,ordem ASC,data_documento DESC,titulo ASC")->fetchAll(PDO::FETCH_ASSOC);$total=count($docs);$ativos=0;$abertos=0;$destaques=0;foreach($docs as $d){if($d['ativo'])$ativos++;if($d['estado']==='aberto')$abertos++;if($d['destaque'])$destaques++;}
?>
