<div class="rh-grid-admin"><div class="rh-card"><h3><?= $editar?'Editar documento':'Novo documento/anexo' ?></h3><form method="POST" enctype="multipart/form-data" class="rh-form"><input type="hidden" name="acao" value="documento"><input type="hidden" name="id" value="<?= htmlspecialchars($editar['id']??0) ?>"><input type="hidden" name="ficheiro_atual" value="<?= htmlspecialchars($editar['ficheiro_guardado']??'') ?>"><input type="hidden" name="ficheiro_original_atual" value="<?= htmlspecialchars($editar['ficheiro_original']??'') ?>"><input type="hidden" name="imagem_atual" value="<?= htmlspecialchars($editar['imagem']??'') ?>"><label>Título *</label><input name="titulo" value="<?= htmlspecialchars($editar['titulo']??'') ?>" required><div class="rh-form-grid"><div><label>Categoria</label><select name="categoria"><?php foreach($categorias as $k=>$v): ?><option value="<?= htmlspecialchars($k) ?>" <?= (($editar['categoria']??'')===$k)?'selected':'' ?>><?= htmlspecialchars($v) ?></option><?php endforeach; ?></select></div><div><label>Estado</label><select name="estado"><?php foreach($estados as $k=>$v): ?><option value="<?= htmlspecialchars($k) ?>" <?= (($editar['estado']??'')===$k)?'selected':'' ?>><?= htmlspecialchars($v) ?></option><?php endforeach; ?></select></div></div><label>Descrição</label><textarea name="descricao"><?= htmlspecialchars($editar['descricao']??'') ?></textarea><div class="rh-form-grid"><div><label>Ficheiro PDF/Word/Excel/Imagem</label><input type="file" name="ficheiro" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.webp"></div><div><label>Imagem de capa opcional</label><input type="file" name="imagem" accept="image/*"></div></div><?php if(!empty($editar['ficheiro_original'])): ?><small>Ficheiro atual: <?= htmlspecialchars($editar['ficheiro_original']) ?></small><?php endif; ?><div class="rh-form-grid"><div><label>Data</label><input type="date" name="data_documento" value="<?= htmlspecialchars($editar['data_documento']??'') ?>"></div><div><label>Ordem</label><input type="number" name="ordem" value="<?= htmlspecialchars($editar['ordem']??0) ?>"></div></div><div class="rh-checks"><label><input type="checkbox" name="destaque" <?= !empty($editar['destaque'])?'checked':'' ?>> Destaque</label><label><input type="checkbox" name="ativo" <?= !isset($editar['ativo'])||!empty($editar['ativo'])?'checked':'' ?>> Ativo</label></div><div class="rh-actions"><button class="btn" type="submit"><?= $editar?'Guardar documento':'Criar documento' ?></button><?php if($editar): ?><a class="btn secondary" href="recursos-humanos.php">Cancelar</a><?php endif; ?></div></form></div><div class="rh-card"><h3>Documentos existentes</h3><?php foreach($docs as $d): ?><div class="rh-row"><div class="rh-icon"><i class="bi bi-paperclip"></i></div><div><h4><?= htmlspecialchars($d['titulo']) ?></h4><p><span class="badge"><?= htmlspecialchars($categorias[$d['categoria']]??$d['categoria']) ?></span><span class="badge <?= $d['estado']==='aberto'?'open':'' ?>"><?= htmlspecialchars($estados[$d['estado']]??$d['estado']) ?></span><?php if(!empty($d['data_documento'])): ?><span class="badge"><?= date('d/m/Y',strtotime($d['data_documento'])) ?></span><?php endif; ?><?php if(!$d['ativo']): ?><span class="badge off">Inativo</span><?php endif; ?><?php if($d['destaque']): ?><span class="badge gold">Destaque</span><?php endif; ?></p></div><div class="rh-actions"><a class="btn secondary" href="recursos-humanos.php?editar=<?= (int)$d['id'] ?>">Editar</a><a class="btn secondary" href="recursos-humanos.php?toggle=<?= (int)$d['id'] ?>"><?= $d['ativo']?'Ocultar':'Mostrar' ?></a><a class="btn danger" onclick="return confirm('Apagar este documento?')" href="recursos-humanos.php?apagar=<?= (int)$d['id'] ?>">Apagar</a></div></div><?php endforeach; ?><?php if(empty($docs)): ?><p>Ainda não existem documentos de Recursos Humanos.</p><?php endif; ?></div></div><?php require_once 'includes/footer.php'; ?>
